// ─── File: CqrsDemo.java ───
// Multiple package-private top-level classes for a runnable, framework-free CQRS demo.
package com.bank.cqrs;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CqrsDemo {

    private static final Logger log = Logger.getLogger("CQRS");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // --- Write side storage ---
        WriteStore writeStore = new WriteStore();
        writeStore.save(new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        writeStore.save(new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));

        // --- Read side storage (denormalized projections) ---
        ReadStore readStore = new ReadStore();
        readStore.put(new AccountStatementView("SAV2001", "Rajesh Kumar",
                new BigDecimal("1000000"), "none"));
        readStore.put(new AccountStatementView("CUR3001", "Priya Sharma",
                new BigDecimal("250000"), "none"));

        // Wire the projection updater to react to domain events.
        ProjectionUpdater projection = new ProjectionUpdater(readStore);
        TransferCommandHandler handler =
                new TransferCommandHandler(writeStore, projection);

        // --- Command side: move Rs.50,000 from Rajesh to Priya ---
        handler.handle(new TransferCommand("SAV2001", "CUR3001",
                new BigDecimal("50000")));

        // --- Query side: read the fast, denormalized views ---
        StatementQueryHandler queries = new StatementQueryHandler(readStore);
        AccountStatementView rajeshView = queries.byAccount("SAV2001");
        AccountStatementView priyaView = queries.byAccount("CUR3001");
        log.info(() -> "QUERY SAV2001 → balance Rs." + rajeshView.balance()
                + " last: " + rajeshView.lastActivity());
        log.info(() -> "QUERY CUR3001 → balance Rs." + priyaView.balance()
                + " last: " + priyaView.lastActivity());
    }
}

// ─── command/TransferCommand.java ───
record TransferCommand(String fromId, String toId, BigDecimal amount) { }

// ─── event/MoneyTransferred.java ───
record MoneyTransferred(String fromId, String toId, BigDecimal amount,
                        BigDecimal fromBalance, BigDecimal toBalance,
                        Instant at) { }

// ─── domain/Account.java (aggregate — enforces invariants) ───
class Account {
    private final String accountId;
    private final String holder;
    private BigDecimal balance;

    Account(String accountId, String holder, BigDecimal balance) {
        this.accountId = accountId;
        this.holder = holder;
        this.balance = balance;
    }

    void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient funds in " + accountId);
        balance = balance.subtract(amount);
    }

    void credit(BigDecimal amount) { balance = balance.add(amount); }

    String getAccountId() { return accountId; }
    String getHolder() { return holder; }
    BigDecimal getBalance() { return balance; }
}

// ─── command/TransferCommandHandler.java ───
class TransferCommandHandler {
    private static final Logger log = Logger.getLogger("CQRS");
    private final WriteStore writeStore;
    private final ProjectionUpdater projection;

    TransferCommandHandler(WriteStore writeStore, ProjectionUpdater projection) {
        this.writeStore = writeStore;
        this.projection = projection;
    }

    void handle(TransferCommand cmd) {
        // Load aggregates from the WRITE model.
        Account from = writeStore.find(cmd.fromId());
        Account to = writeStore.find(cmd.toId());
        // Enforce invariants inside the aggregates.
        from.debit(cmd.amount());
        to.credit(cmd.amount());
        writeStore.save(from);
        writeStore.save(to);
        log.info(() -> "COMMAND transfer Rs." + cmd.amount()
                + " " + cmd.fromId() + " → " + cmd.toId() + " committed");
        // Emit a domain event; the read side reacts to it.
        MoneyTransferred event = new MoneyTransferred(
                cmd.fromId(), cmd.toId(), cmd.amount(),
                from.getBalance(), to.getBalance(), Instant.now());
        projection.on(event);
    }
}

// ─── projection/ProjectionUpdater.java (updates read model from events) ───
class ProjectionUpdater {
    private static final Logger log = Logger.getLogger("CQRS");
    private final ReadStore readStore;

    ProjectionUpdater(ReadStore readStore) { this.readStore = readStore; }

    void on(MoneyTransferred e) {
        AccountStatementView from = readStore.get(e.fromId());
        AccountStatementView to = readStore.get(e.toId());
        readStore.put(new AccountStatementView(from.accountId(), from.holder(),
                e.fromBalance(), "Debit Rs." + e.amount() + " to " + e.toId()));
        readStore.put(new AccountStatementView(to.accountId(), to.holder(),
                e.toBalance(), "Credit Rs." + e.amount() + " from " + e.fromId()));
        log.info(() -> "PROJECTION updated statement views for "
                + e.fromId() + " and " + e.toId());
    }
}

// ─── query/AccountStatementView.java (denormalized read model) ───
record AccountStatementView(String accountId, String holder,
                            BigDecimal balance, String lastActivity) { }

// ─── query/StatementQueryHandler.java (serves fast reads) ───
class StatementQueryHandler {
    private final ReadStore readStore;
    StatementQueryHandler(ReadStore readStore) { this.readStore = readStore; }
    AccountStatementView byAccount(String id) { return readStore.get(id); }
}

// ─── write-side storage ───
class WriteStore {
    private final Map<String, Account> db = new ConcurrentHashMap<>();
    void save(Account a) { db.put(a.getAccountId(), a); }
    Account find(String id) { return db.get(id); }
}

// ─── read-side storage ───
class ReadStore {
    private final Map<String, AccountStatementView> db = new ConcurrentHashMap<>();
    void put(AccountStatementView v) { db.put(v.accountId(), v); }
    AccountStatementView get(String id) { return db.get(id); }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
